#!/usr/bin/env python3
from __future__ import annotations

import inspect
import platform
import sys
import types
from pathlib import Path


def _run_impl(source: str, impl_name: str) -> int:
    module_name = f'{__name__}.{impl_name}'
    module = types.ModuleType(module_name)
    module.__file__ = str(Path(__file__).resolve())
    sys.modules[module_name] = module
    namespace = module.__dict__
    exec(compile(source, str(Path(__file__).resolve()), 'exec'), namespace, namespace)
    main_fn = namespace.get('main')
    if not callable(main_fn):
        raise RuntimeError(f"Selected implementation '{impl_name}' for 'genai_build' does not define main()")
    sig = inspect.signature(main_fn)
    if len(sig.parameters) == 0:
        return int(main_fn())
    if len(sig.parameters) == 1:
        return int(main_fn(sys.argv))
    raise RuntimeError(f"Selected implementation '{impl_name}' for 'genai_build' has unsupported main() signature")


def main() -> int:
    if platform.system().strip().lower().startswith('win'):
        return _run_impl(_WINDOWS_IMPL, 'windows')
    return _run_impl(_LINUX_IMPL, 'linux')


_LINUX_IMPL = 'from __future__ import annotations\n\nimport os\nimport subprocess\nfrom datetime import datetime\n\nfrom _linux_common import CONFIG_FILE, PROJECT_ROOT, apply_optional_proxy, load_config, resolve_path\n\n\nREPO_URL = "https://github.com/openvinotoolkit/openvino.genai.git"\n\n\ndef log(msg: str) -> None:\n\tts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")\n\tprint(f"\\n[{ts}] {msg}")\n\n\ndef _run(cmd: list[str], *, cwd: str | None = None, env: dict[str, str] | None = None) -> None:\n\trc = subprocess.run(cmd, cwd=cwd, env=env).returncode\n\tif rc != 0:\n\t\traise RuntimeError(f"Command failed ({rc}): {\' \'.join(cmd)}")\n\n\ndef main() -> int:\n\tlog("Checking required commands")\n\tfor cmd in ("git", "python3"):\n\t\tif subprocess.run(["bash", "-lc", f"command -v {cmd} >/dev/null 2>&1"]).returncode != 0:\n\t\t\tprint(f"Error: required command \'{cmd}\' is not installed or not in PATH.")\n\t\t\treturn 1\n\n\tif not CONFIG_FILE.is_file():\n\t\tprint(f"Error: Missing config file at {CONFIG_FILE}")\n\t\treturn 1\n\n\tcfg = load_config()\n\tenv = dict(os.environ)\n\tapply_optional_proxy(cfg, env)\n\tif env != os.environ:\n\t\tlog(f"Applied proxy settings from {CONFIG_FILE}")\n\n\tbuild_dir_raw = cfg.get("build_dir")\n\tif not build_dir_raw:\n\t\tprint(f"Error: Missing build_dir in {CONFIG_FILE}")\n\t\treturn 1\n\n\tbuild_dir = resolve_path(str(build_dir_raw))\n\trepo_dir = build_dir / "openvino.genai"\n\tllm_bench_dir = repo_dir / "tools" / "llm_bench"\n\tvenv_dir = llm_bench_dir / "python-env"\n\n\tbuild_dir.mkdir(parents=True, exist_ok=True)\n\tif repo_dir.is_dir() and not llm_bench_dir.is_dir():\n\t\tlog(f"Existing repository layout is invalid at \'{repo_dir}\' (missing \'tools/llm_bench\')")\n\t\tlog(f"Deleting \'{repo_dir}\' and recloning from scratch")\n\t\t_run(["rm", "-rf", str(repo_dir)], env=env)\n\n\tif not repo_dir.is_dir():\n\t\tlog(f"Cloning repository: {REPO_URL}")\n\t\t_run(["git", "clone", REPO_URL, str(repo_dir)], env=env)\n\telse:\n\t\tlog(f"Repository already exists at \'{repo_dir}\', skipping clone")\n\n\tlog(f"Working directory: {llm_bench_dir}")\n\tenv["GIT_CLONE_PROTECTION_ACTIVE"] = "false"\n\tlog("Set GIT_CLONE_PROTECTION_ACTIVE=false")\n\n\tif not venv_dir.is_dir():\n\t\tlog("Creating Python virtual environment")\n\t\t_run(["python3", "-m", "venv", str(venv_dir)], env=env)\n\telse:\n\t\tlog(f"Virtual environment already exists at \'{venv_dir}\'")\n\n\tpy_bin = venv_dir / "bin" / "python"\n\tpip_bin = venv_dir / "bin" / "pip"\n\tif not py_bin.is_file() or not pip_bin.is_file():\n\t\tprint(f"Error: invalid virtual environment at {venv_dir}")\n\t\treturn 1\n\n\tlog("Upgrading pip")\n\t_run([str(py_bin), "-m", "pip", "install", "--upgrade", "pip"], cwd=str(llm_bench_dir), env=env)\n\n\tlog("Installing requirements")\n\t_run([str(pip_bin), "install", "-r", "requirements.txt"], cwd=str(llm_bench_dir), env=env)\n\n\tlog("Installing pinned transformers version")\n\t_run([str(pip_bin), "install", "transformers==4.55.4"], cwd=str(llm_bench_dir), env=env)\n\n\tlog("Installing compatible diffusers version")\n\t_run([str(pip_bin), "install", "diffusers<0.35"], cwd=str(llm_bench_dir), env=env)\n\n\tlog("Done. Environment setup completed (no model download/quantization run).")\n\treturn 0\n\n\nif __name__ == "__main__":\n\traise SystemExit(main())\n'


_WINDOWS_IMPL = 'from __future__ import annotations\n\nimport os\nimport shutil\nimport sys\nfrom pathlib import Path\n\nfrom _windows_common_ import apply_dependency_paths, apply_proxy_env_from_config, dependency_root, ensure_dir, ensure_tool, load_config, project_root, resolve_path, run_cmd\n\n\ndef venv_python(venv_root: Path) -> Path:\n    if os.name == "nt":\n        return venv_root / "Scripts" / "python.exe"\n    return venv_root / "bin" / "python"\n\n\ndef parse_auto_update(cfg: dict) -> bool:\n    top = cfg.get("auto_update")\n    if top is not None:\n        return str(top).strip().lower() in {"true", "1", "yes"}\n    ll_cfg = cfg.get("llamacpp", {}) or {}\n    return str(ll_cfg.get("auto_update", "true")).strip().lower() in {"true", "1", "yes"}\n\n\ndef load_logged_commit(log_file: Path) -> str:\n    if not log_file.is_file():\n        return ""\n    lines = log_file.read_text(encoding="utf-8", errors="ignore").splitlines()\n    if not lines:\n        return ""\n    return lines[0].split()[0].strip()\n\n\ndef write_commit_log(git: str, repo_dir: Path, log_file: Path, env: dict[str, str]) -> None:\n    full_commit = run_cmd([git, "-C", str(repo_dir), "rev-parse", "HEAD"], env=env, capture_output=True).stdout.strip()\n    short = full_commit[:9]\n    subject = run_cmd([git, "-C", str(repo_dir), "log", "-1", "--format=%s"], env=env, capture_output=True).stdout.strip()\n    ensure_dir(log_file.parent)\n    log_file.write_text(f"{short} {subject}\\n", encoding="utf-8")\n\n\ndef remove_tree_with_retries(path: Path, retries: int = 4) -> bool:\n    if not path.exists():\n        return True\n    for _ in range(retries):\n        try:\n            shutil.rmtree(path)\n        except Exception:\n            pass\n        if not path.exists():\n            return True\n    return not path.exists()\n\n\ndef genai_ready(repo_dir: Path) -> bool:\n    bench_dir = repo_dir / "tools" / "llm_bench"\n    venv_dir = bench_dir / "python-env"\n    py = venv_python(venv_dir)\n    bench_script = bench_dir / "benchmark.py"\n    req_file = bench_dir / "requirements.txt"\n    return bench_dir.is_dir() and venv_dir.is_dir() and py.is_file() and bench_script.is_file() and req_file.is_file()\n\n\ndef main() -> int:\n    root = project_root(__file__)\n    cfg = load_config(root)\n    env = dict(os.environ)\n    apply_proxy_env_from_config(cfg, env)\n    dep_root = dependency_root(root, cfg)\n    ensure_dir(dep_root)\n    apply_dependency_paths(dep_root, env)\n\n    build_dir = resolve_path(root, cfg.get("build_dir"), "./BUILD")\n    logs_dir = resolve_path(root, cfg.get("logs_dir"), "./logs")\n    repo_dir = build_dir / "openvino.genai"\n    bench_dir = repo_dir / "tools" / "llm_bench"\n    venv_dir = bench_dir / "python-env"\n\n    ll_mode = str((cfg.get("llamacpp", {}) or {}).get("use", "build")).strip().lower()\n    genai_log = logs_dir / f"openvino_genai_commit_{ll_mode}.txt"\n\n    auto_update = parse_auto_update(cfg)\n    print(f"auto_update={auto_update} (openvino.genai)")\n\n    ensure_dir(build_dir)\n    ensure_dir(logs_dir)\n    git_exe = ensure_tool("git", dep_root, env)\n\n    remote_head = ""\n    if auto_update:\n        remote_head = run_cmd(\n            [git_exe, "ls-remote", "https://github.com/openvinotoolkit/openvino.genai.git", "HEAD"],\n            env=env,\n            capture_output=True,\n        ).stdout.split()[0].strip()\n\n    logged = load_logged_commit(genai_log)\n    remote_short = remote_head[: len(logged)] if logged and remote_head else ""\n    same_commit = True\n    if auto_update:\n        same_commit = bool(logged and remote_short == logged)\n\n    ready = genai_ready(repo_dir)\n    full_rebuild = not same_commit\n    build_missing = not ready\n\n    if full_rebuild:\n        print("GenAI plan: commit changed or missing, rebuild openvino.genai setup")\n    elif build_missing:\n        print("GenAI plan: incremental, setup missing prerequisites")\n    else:\n        print("GenAI plan: up to date, skip setup")\n\n    if full_rebuild and repo_dir.exists():\n        if not remove_tree_with_retries(repo_dir):\n            print(f"Warning: failed to clean openvino.genai directory (locked), falling back to in-place sync: {repo_dir}")\n            if auto_update and remote_head:\n                try:\n                    run_cmd([git_exe, "-C", str(repo_dir), "fetch", "--all", "--tags", "--prune"], env=env)\n                    run_cmd([git_exe, "-C", str(repo_dir), "reset", "--hard", remote_head], env=env)\n                    run_cmd([git_exe, "-C", str(repo_dir), "clean", "-fdx"], env=env, check=False)\n                    print("GenAI in-place sync completed")\n                except Exception as exc:\n                    print(f"Warning: GenAI in-place sync failed, continuing with existing repo state ({exc})")\n\n    if not full_rebuild and not build_missing:\n        if repo_dir.is_dir():\n            write_commit_log(git_exe, repo_dir, genai_log, env)\n        print("GenAI build/setup completed (no changes)")\n        return 0\n\n    if not repo_dir.is_dir():\n        run_cmd([git_exe, "clone", "https://github.com/openvinotoolkit/openvino.genai.git", str(repo_dir)], env=env)\n\n    if not bench_dir.is_dir():\n        raise RuntimeError(f"Missing llm_bench directory: {bench_dir}")\n\n    if not venv_dir.is_dir():\n        run_cmd([sys.executable, "-m", "venv", str(venv_dir)], cwd=bench_dir, env=env)\n\n    py = venv_python(venv_dir)\n    if not py.is_file():\n        raise RuntimeError(f"Venv python not found: {py}")\n\n    run_cmd([str(py), "-m", "pip", "install", "--upgrade", "pip"], cwd=bench_dir, env=env)\n    req_file = bench_dir / "requirements.txt"\n    if req_file.is_file():\n        run_cmd([str(py), "-m", "pip", "install", "-r", str(req_file)], cwd=bench_dir, env=env)\n    run_cmd([str(py), "-m", "pip", "install", "transformers==4.55.4", "diffusers<0.35"], cwd=bench_dir, env=env)\n\n    write_commit_log(git_exe, repo_dir, genai_log, env)\n\n    print("GenAI build/setup completed")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'


if __name__ == '__main__':
    raise SystemExit(main())
